kekValue := os.Getenv("RE0AUTH_KEK")
if kekValue == "" {
	if f.Vault.KEKEnv == "" {
		return settings{}, errors.New("the vault KEK is required: set RE0AUTH_KEK or vault.kek_env")
	}
	resolved, err := config.Secret(f.Vault.KEKEnv, "vault.kek_env")
	if err != nil {
		return settings{}, err
	}
	kekValue = resolved
}
cfg.KEK, err = decodeKEK32(kekValue)

driver := config.FirstNonEmpty(strings.TrimSpace(os.Getenv("RE0AUTH_STORAGE_DRIVER")), f.Storage.Driver)
switch driver {
case "":
	if f.Storage.DSNEnv != "" || cfg.DatabaseURL != "" {
		driver = "postgres"
	} else {
		driver = "memory"
		cfg.StorageReason = "no DATABASE_URL is configured"
	}
case "memory":
	driver = "memory"
	cfg.StorageReason = "storage.driver is memory"
case "postgres":
	if cfg.DatabaseURL == "" {
		dsnEnv := f.Storage.DSNEnv
		if dsnEnv == "" {
			dsnEnv = "DATABASE_URL"
		}
		dsn, err := config.Secret(dsnEnv, "storage.dsn_env")
		if err != nil {
			return settings{}, err
		}
		cfg.DatabaseURL = dsn
	}
default:
	return settings{}, fmt.Errorf("storage.driver %q must be \"memory\" or \"postgres\"", driver)
}

res.PseudonymDestroyed = d.cfg.Pseudonyms != nil

// The record is written after every store is clear, so it can state the result
// rather than a promise...
if err := d.record(ctx, actor, subject, audit.OutcomeOK, res, ""); err != nil {
	return res, err
}

if d.cfg.Pseudonyms != nil {
	if err := d.cfg.Pseudonyms.Destroy(ctx, string(subject)); err != nil {
		res.PseudonymDestroyed = false
		return d.fail(ctx, actor, subject, "pseudonym", fmt.Errorf(
			"lifecycle: the account was erased but its audit history is still linkable: %w", err), res)
	}
}
