func hasUniversalPrefix(prefixes []netip.Prefix) bool {
	for _, p := range prefixes {
		if p.Bits() == 0 {
			return true
		}
	}
	return false
}

add := func(role, name string) {
	if strings.TrimSpace(name) != "" {
		lines = append(lines, role+"="+name)
	}
}
